// OpenCode Anthropic User-Agent Plugin
// Generated by setup_ua_plugin.py
// Based on: https://github.com/dotCipher/opencode-anthropic-user-agent-plugin
//
// Injects a configurable User-Agent header for all Anthropic API requests.
// Override via env: OPENCODE_ANTHROPIC_USER_AGENT

const ANTHROPIC_HOSTS = [
  "api.anthropic.com",
  "console.anthropic.com",
  "platform.claude.com",
  "claude.ai",
];

const DEFAULT_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36";

function isAnthropicHost(url) {
  try {
    const hostname = new URL(url).hostname;
    return ANTHROPIC_HOSTS.some(
      (h) => hostname === h || hostname.endsWith("." + h)
    );
  } catch {
    return false;
  }
}

// Patch fetch once at module load
const _origFetch = globalThis.fetch;
globalThis.fetch = function patchedFetch(input, init) {
  const url = typeof input === "string" ? input : input?.url || "";
  if (isAnthropicHost(url)) {
    const ua =
      (typeof process !== "undefined" && process.env?.OPENCODE_ANTHROPIC_USER_AGENT) ||
      DEFAULT_UA;
    init = init || {};
    init.headers = init.headers || {};
    // Support both Headers object and plain object
    if (typeof init.headers.set === "function") {
      init.headers.set("User-Agent", ua);
    } else {
      init.headers["User-Agent"] = ua;
    }
  }
  return _origFetch.call(this, input, init);
};

// Export as OpenCode plugin (no-op hooks — the fetch patch does all the work)
export default function AnthropicUserAgentPlugin() {
  return {};
}
